$ErrorActionPreference = 'Stop'
if ($PSVersionTable.PSEdition -ne 'Desktop' -or $PSVersionTable.PSVersion.Major -ne 5 -or $env:RUNNER_ENVIRONMENT -ne 'github-hosted') {
    throw 'Stock PowerShell 5.1 on a hosted disposable Windows runner is required.'
}
Add-Type -AssemblyName System.Net.Http
$handler = New-Object Net.Http.HttpClientHandler
$handler.AllowAutoRedirect = $false
$http = New-Object Net.Http.HttpClient($handler)
$http.DefaultRequestHeaders.UserAgent.ParseAdd('Mosaic-Private-Trial-Qualification')
$http.DefaultRequestHeaders.Authorization = New-Object Net.Http.Headers.AuthenticationHeaderValue('Bearer', $env:GITHUB_TRIAL_READ_TOKEN)
try {
    $response = $http.GetAsync('https://api.github.com/repos/TanujBuilds/Mosaic/actions/artifacts/14767202712/zip').GetAwaiter().GetResult()
    if ([int]$response.StatusCode -ne 302) { throw 'GitHub did not issue a time-limited artifact URL.' }
    $url = $response.Headers.Location
    if ($url.Scheme -ne 'https' -or -not ($url.Host.EndsWith('.blob.core.windows.net') -or $url.Host.EndsWith('.actions.githubusercontent.com'))) {
        throw 'Unexpected download origin'
    }
} finally { $http.Dispose(); $handler.Dispose() }
Remove-Item Env:GITHUB_TRIAL_READ_TOKEN -ErrorAction SilentlyContinue
$userData = [Environment]::GetFolderPath('LocalApplicationData')
$root = Join-Path $userData 'Mosaic Windows Trial 784766c'
if (Test-Path -LiteralPath $root) { throw 'Trial fixture staging already exists' }
[void][IO.Directory]::CreateDirectory($root)
$part = Join-Path $root 'candidate.part'
$curl = Join-Path ([Environment]::SystemDirectory) 'curl.exe'
& $curl -q --globoff --fail --show-error --silent --proto '=https' --range '0-1048575' --output $part -- $url.AbsoluteUri
if ($LASTEXITCODE -ne 0 -or (Get-Item -LiteralPath $part).Length -ne 1048576) { throw 'Could not persist the interrupted transfer fixture.' }
Write-Output 'Independent partial HTTPS transfer retained 1,048,576 bytes.'
$script = @'
& { $ErrorActionPreference='Stop'; $url='__SIGNED_URL__'; $drive=[Environment]::GetFolderPath('LocalApplicationData'); if(-not $drive){throw 'No local Windows user profile'}; $root=Join-Path $drive 'Mosaic Windows Trial 784766c'; function Plain([string]$p){$x=Get-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue;if($x -and ($x.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'The trial path is linked'}}; Plain $root; [void][IO.Directory]::CreateDirectory($root); $lockPath=Join-Path $root 'install.lock'; Plain $lockPath; $lock=[IO.File]::Open($lockPath,'OpenOrCreate','ReadWrite','None'); try { $zip=Join-Path $root 'candidate.zip'; $part=Join-Path $root 'candidate.part'; foreach($f in @($zip,$part)){Plain $f;if([IO.Directory]::Exists($f)){throw 'Invalid trial staging file'}}; function Matches([string]$p,[string]$sha){[IO.File]::Exists($p) -and (Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash -eq $sha}; $outer='9a1fa82e1314b9bfcfe8941d623112cbf1a8099a4967d788f2eb54d5e66784e9'; if(-not (Matches $zip $outer)){ if([IO.File]::Exists($zip)){throw 'Cached trial archive differs from the verified candidate'}; if([IO.File]::Exists($part) -and (Get-Item -LiteralPath $part).Length -ge 114883173 -and -not (Matches $part $outer)){Remove-Item -LiteralPath $part -Force}; if(-not (Matches $part $outer)){ $curl=Join-Path ([Environment]::SystemDirectory) 'curl.exe'; & $curl -q --globoff --fail --show-error --proto '=https' --continue-at - --max-filesize 114883173 --output $part -- $url; if($LASTEXITCODE -ne 0){throw 'Trial download interrupted or expired. Partial bytes were saved.'}; }; if(-not (Matches $part $outer)){throw 'Trial archive did not match its pinned SHA-256'}; [IO.File]::Move($part,$zip); }; $work=Join-Path $root ([guid]::NewGuid().ToString()); [void][IO.Directory]::CreateDirectory($work); try { Expand-Archive -LiteralPath $zip -DestinationPath $work; $bootstrap=Join-Path $work 'install.ps1'; $archive=Join-Path $work 'mosaic-beta-0.1.0-beta.235-win-x64.zip'; $inner='fb99b8a849d6cd42cd80a7a0ad07871f07b648ba5921a9e5cc5cee7d35c9f53b'; if(-not (Matches $bootstrap '6a1e53c0d9874ce6839cc7e65a2db5e6cd8992b3c6bc07b8757e325e828342e1') -or -not (Matches $archive $inner)){throw 'Trial bootstrap or payload checksum changed'}; $project=Join-Path $root 'Invoice trial'; Plain $project; if(-not [IO.Directory]::Exists($project)){ $sampleZip=Join-Path $work 'invoice.zip'; [IO.File]::WriteAllBytes($sampleZip,[Convert]::FromBase64String('')); if(-not (Matches $sampleZip 'ce6ba29820dade2410afb9dcc34a65ab8731b6fa092f791631f0ce3c3f45bb04')){throw 'Trial project checksum changed'}; $sample=Join-Path $work 'invoice'; Expand-Archive -LiteralPath $sampleZip -DestinationPath $sample; [IO.Directory]::Move($sample,$project); }; Push-Location -LiteralPath $project; try { $powershell=Join-Path ([Environment]::SystemDirectory) 'WindowsPowerShell\v1.0\powershell.exe'; & $powershell -NoLogo -NoProfile -ExecutionPolicy Bypass -File $bootstrap -Version '0.1.0-beta.235' -Archive $archive -ArchiveSha256 $inner __GUIDE_ARGS__; if($LASTEXITCODE -ne 0){throw "Mosaic installer exited with code $LASTEXITCODE"}; } finally {Pop-Location}; } finally {Remove-Item -LiteralPath $work -Recurse -Force}; } finally {$lock.Dispose()}; }
'@
try {
    $delivery = [scriptblock]::Create($script.Replace('__SIGNED_URL__',$url.AbsoluteUri.Replace("'","''")).Replace('__GUIDE_ARGS__','-NoGuide'))
} catch { throw 'One-command trial wrapper could not be parsed.' }
& $delivery
$project = Join-Path $root 'Invoice trial'
$head = & git -C $project rev-parse HEAD
if ($LASTEXITCODE -ne 0 -or $head -cne '98a111b90a38da4a850e0b50ddf3129c9294ab28') { throw 'Invoice trial does not have its exact committed baseline.' }
$changes = @(& git -C $project status --porcelain)
if ($LASTEXITCODE -ne 0 -or $changes.Count) { throw 'Invoice trial checkout is not clean.' }
$launcher = Join-Path $userData 'Mosaic Beta/bin/mosaic.exe'
$help = & $launcher --help
if ($LASTEXITCODE -ne 0 -or ($help -join ' ') -notmatch 'Mosaic') { throw 'Verified package did not launch.' }
Write-Output 'Resumed verified candidate in Windows PowerShell 5.1, installed and opened Mosaic, and verified the committed clean invoice project.'
